-- WITH cache_sl AS ( SELECT mri_session_id, CAST(__time AS TIMESTAMP) as cache_time, CAST(route_id AS VARCHAR) as route_id_val, is_cached FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-05-14 00:00:00' AND __time < TIMESTAMP '2026-05-15 00:00:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND is_cached = True ), base AS ( SELECT a.mri_session_id, CAST(a.__time AS TIMESTAMP) AS ts_time_utc, a.event_type, (CAST(a.src_id AS VARCHAR) || '-' || CAST(a.dest_id AS VARCHAR)) AS sd_id, CAST(a.doj AS VARCHAR) AS doj_val, CAST(a.route_id AS VARCHAR) AS route_id_val, -- Join check with 1 second buffer CASE WHEN c.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS is_cached_event FROM user_interaction.api_events a LEFT JOIN cache_sl c ON a.mri_session_id = c.mri_session_id AND a.__time BETWEEN (c.cache_time - INTERVAL '2' SECOND) AND (c.cache_time + INTERVAL '2' SECOND) AND CAST(a.route_id AS VARCHAR) = c.route_id_val WHERE a.__time >= TIMESTAMP '2026-05-14 00:00:00' AND a.__time < TIMESTAMP '2026-05-15 00:00:00' AND a.event_src = 'CAPI' AND a.country = 'IND' AND a.channel = 'MOBILE_APP' AND a.os = 'Android' AND a.event_type IN ( 'Search-Routes', 'SeatLayout-ViewSeats', 'Tentative-MpaxAttribute', 'Tentative-CreateOrder', 'Tentative-OrderInfo', 'Payment-offlinePayments', 'Payment-Conclude' ) ), parameter_check AS ( SELECT *, FIRST_VALUE(sd_id) OVER (PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc) AS first_sd, FIRST_VALUE(doj_val) OVER (PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc) AS first_doj, FIRST_VALUE(route_id_val) OVER (PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc) AS first_route, ROW_NUMBER() OVER (PARTITION BY mri_session_id, event_type ORDER BY ts_time_utc) AS occurrence_rank FROM base ), labeled AS ( SELECT mri_session_id, ts_time_utc, CASE WHEN event_type = 'Search-Routes' THEN /* Toggle the below stub to get deeper and Overall Cut */ 'SRP' -- CASE -- WHEN occurrence_rank = 1 THEN 'First SRP' -- WHEN sd_id = first_sd AND doj_val = first_doj THEN 'Same SD-DOJ SRP' -- ELSE 'Different SRP' -- END WHEN event_type = 'SeatLayout-ViewSeats' THEN /* Toggle the below stub to get deeper and Overall Cut */ CASE WHEN is_cached_event = 1 THEN 'Cached SL' ELSE 'SL' END -- CASE -- WHEN is_cached_event = 1 THEN 'Cached SL' -- WHEN occurrence_rank = 1 THEN 'First SL' -- WHEN route_id_val = first_route THEN 'Same route SL' -- ELSE 'Different route SL' -- END WHEN event_type = 'Tentative-MpaxAttribute' THEN 'CI' WHEN event_type = 'Tentative-CreateOrder' THEN 'TCO' WHEN event_type = 'Tentative-OrderInfo' THEN 'Pay' WHEN event_type = 'Payment-offlinePayments' THEN 'AddPay' WHEN event_type = 'Payment-Conclude' THEN 'Buddy' END AS step_label FROM parameter_check ), final_paths AS ( SELECT mri_session_id, -- Aggregate directly from 'labeled' without deduping ARRAY_JOIN(ARRAY_AGG(step_label ORDER BY ts_time_utc), ' > ') AS behaviour_path, MAX(CASE WHEN step_label = 'Pay' THEN 1 ELSE 0 END) as reached_pay FROM labeled GROUP BY mri_session_id ) SELECT behaviour_path, COUNT(*) AS distinct_sessions FROM final_paths --- TOGGLE SECTION --- WHERE reached_pay = 1 ---------------------- GROUP BY 1 ORDER BY 2 DESC, 1;
